def recursive_list_sum(lst):
    total = 0
    for element in lst:
        if isinstance(element, list):  # Check if the element is a list
            total += recursive_list_sum(element)  # Recursively sum the elements of the nested list
        else:
            total += element  # Directly add non-list elements
    return total

def bell_number(n):
    # Initialize a list to store the Bell numbers
    bell = [0] * (n + 1)
    bell[0] = 1  # Base case: B_0 = 1

    # Compute Bell numbers using the recursive relation
    for i in range(1, n + 1):
        bell[i] = 0
        for j in range(i):
            bell[i] += bell[j] * binomial_coefficient(i - 1, j)

    return bell[n]

# Helper function to compute binomial coefficient (n choose k)
def binomial_coefficient(n, k):
    if k > n - k:
        k = n - k
    result = 1
    for m in range(k):
        result *= (n - m)
        result //= (m + 1)
    return result

