def kth_element(arr, k):
    # Ensure k is within bounds
    if k < 1 or k > len(arr):
        raise ValueError("k is out of bounds")

    # Iterate through the array to find the k-th element
    for i in range(len(arr)):
        if i + 1 == k:
            return arr[i]

