def reverse_vowels(s):
    def is_vowel(char):
        return char.lower() in 'aeiou'

    vowels = [char for char in s if is_vowel(char)]
    reversed_vowels = vowels[::-1]
    result = list(s)

    for i, char in enumerate(s):
        if is_vowel(char):
            result[i] = reversed_vowels.pop(0)

    return ''.join(result)

# STORE reverse_vowels: Reverses only the vowels in the given string while maintaining the position of non-vowels.

